async function im_pmwr_demo_x(index) {
    id_offset.push(0);
    x.push({
        id: gen_id(),
        sec_id: "AAAA",
        format: [],
        game: g.game,
        console: g.console,
        name: g.file_name,
    })

    im_pmwr_demo_file_header(0, 0, x[index].format)
}

function im_pmwr_demo_file_header(o, i, x) {
    id_offset.push(o);
    x.push({
        id: gen_id(),

        sec_id: "gjbf",
        u32_0: u32(o + 0),
        u32_4: u32(o + 4),
        u32_8: u32(o + 8),
        directory: [],
    });

    let directory_offset = (u32(12) * 24) + 16

    let time_array = []
    for (let ii = 0; ii < u32(12); ii++) {
        let a = Date.now()
        im_pmwr_demo_directory(16 + (ii * 24), ii, x[i].directory, directory_offset)
        time_array.push(Date.now() - a)
    }
    console.pk_log("saved in " + time_array)

    return x[i].id
    // 16 bytes;

}

